CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE, email TEXT NOT NULL DEFAULT '', password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('member','admin')), enabled INTEGER NOT NULL DEFAULT 1, generation INTEGER NOT NULL DEFAULT 1, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, data BLOB NOT NULL, expiry INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tokens(hash TEXT PRIMARY KEY, kind TEXT NOT NULL, username TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', user_id INTEGER REFERENCES users(id), expires TEXT NOT NULL, consumed TEXT);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, audience TEXT NOT NULL DEFAULT 'member', access_service INTEGER REFERENCES services(id), position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS services(id INTEGER PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, category_id INTEGER REFERENCES categories(id) ON DELETE RESTRICT, published INTEGER NOT NULL DEFAULT 0, archived INTEGER NOT NULL DEFAULT 0, audience TEXT NOT NULL DEFAULT 'member', details_audience TEXT NOT NULL DEFAULT 'access', access_service INTEGER REFERENCES services(id), mode TEXT NOT NULL DEFAULT 'info' CHECK(mode IN ('info','request','external')), position INTEGER NOT NULL DEFAULT 0, featured INTEGER NOT NULL DEFAULT 0, config TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS links(id INTEGER PRIMARY KEY, label TEXT NOT NULL, url TEXT NOT NULL DEFAULT '', placement TEXT NOT NULL CHECK(placement IN ('global','category','service')), parent_id INTEGER, access_service INTEGER REFERENCES services(id), audience TEXT NOT NULL DEFAULT 'member', position INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 1, style TEXT NOT NULL DEFAULT 'secondary', new_tab INTEGER NOT NULL DEFAULT 1, icon TEXT NOT NULL DEFAULT 'link', description TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS requests(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), service_id INTEGER NOT NULL REFERENCES services(id), service_name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('access','support')), state TEXT NOT NULL, reason TEXT NOT NULL, fields TEXT NOT NULL DEFAULT '[]', requested_end TEXT NOT NULL DEFAULT '', created TEXT NOT NULL, updated TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, CHECK((kind='access' AND state IN ('Pending','Needs Information','Approved - Setup Pending','Fulfilled','Denied','Cancelled')) OR (kind='support' AND state IN ('Open','Waiting for Member','Resolved','Cancelled'))));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_request ON requests(user_id,service_id) WHERE kind='access' AND state IN ('Pending','Needs Information','Approved - Setup Pending');
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL REFERENCES requests(id), actor_id INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS private_notes(id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL REFERENCES requests(id), actor_id INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transitions(id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL REFERENCES requests(id), actor_id INTEGER NOT NULL REFERENCES users(id), from_state TEXT NOT NULL, to_state TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS access_records(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), service_id INTEGER NOT NULL REFERENCES services(id), service_name TEXT NOT NULL DEFAULT '', state TEXT NOT NULL CHECK(state IN ('active','expired','revoked')), granted TEXT NOT NULL, expires TEXT NOT NULL DEFAULT '', next_steps TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, UNIQUE(user_id,service_id));
CREATE TABLE IF NOT EXISTS access_history(id INTEGER PRIMARY KEY, access_id INTEGER NOT NULL REFERENCES access_records(id), actor_id INTEGER REFERENCES users(id), state TEXT NOT NULL, granted TEXT NOT NULL, expires TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS followups(id INTEGER PRIMARY KEY, access_id INTEGER NOT NULL REFERENCES access_records(id), reason TEXT NOT NULL, created TEXT NOT NULL, completed TEXT, actor_id INTEGER REFERENCES users(id));
CREATE UNIQUE INDEX IF NOT EXISTS one_open_followup ON followups(access_id) WHERE completed IS NULL;
CREATE TABLE IF NOT EXISTS announcements(id INTEGER PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, placement TEXT NOT NULL DEFAULT 'global', parent_id INTEGER, audience TEXT NOT NULL DEFAULT 'member', access_service INTEGER REFERENCES services(id), starts TEXT NOT NULL DEFAULT '', ends TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS media(id TEXT PRIMARY KEY, service_id INTEGER REFERENCES services(id), filename TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), request_id INTEGER REFERENCES requests(id), access_id INTEGER REFERENCES access_records(id), text TEXT NOT NULL, created TEXT NOT NULL, read_at TEXT);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, target TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), name TEXT NOT NULL DEFAULT 'Waypoint', description TEXT NOT NULL DEFAULT 'Good company. Great places to spend your time.', accent TEXT NOT NULL DEFAULT '#a7c4ad', public INTEGER NOT NULL DEFAULT 0, logo TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset INTEGER NOT NULL);
INSERT OR IGNORE INTO settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS token_recommendations(token_hash TEXT NOT NULL REFERENCES tokens(hash) ON DELETE CASCADE,service_id INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,PRIMARY KEY(token_hash,service_id));
CREATE TABLE IF NOT EXISTS recommendations(user_id INTEGER NOT NULL REFERENCES users(id),service_id INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,PRIMARY KEY(user_id,service_id));
